impl<'a> Queries<'a> {
    pub fn as_parse_tree(&'a self) -> ParseTree<'a> {
        ParseTree::Queries(self)
    }
    pub fn child(&self, index: usize) -> Option<ParseTree<'a>> {
        match self {
            Queries::Alt0 {
                queries,
                layout,
                final_query,
                ..
            } => match index {
                0 => Some(ParseTree::Star0(queries)),
                1 => Some(ParseTree::Layout(layout)),
                2 => Some(ParseTree::Opt0(final_query)),
                _ => None,
            },
            Queries::Amb(alts) => alts.get(index).copied().map(ParseTree::Queries),
        }
    }
    pub fn child_count(&self) -> usize {
        match self {
            Queries::Alt0 { .. } => 3usize,
            Queries::Amb(alts) => alts.len(),
        }
    }
    pub fn span(&self) -> Span {
        match self {
            Queries::Alt0 { span, .. } => *span,
            Queries::Amb(alts) => alts[0].span(),
        }
    }
    pub fn display_name(&self) -> &'static str {
        match self {
            Queries::Amb(_) => "Amb",
            _ => "Queries",
        }
    }
    pub fn origin(&self) -> Option<Origin> {
        None
    }
    pub fn queries(&self) -> &'a Star0<'a> {
        match self {
            Queries::Alt0 { queries, .. } => queries,
            Queries::Amb(_) => panic!("Queries is ambiguous"),
        }
    }
    pub fn layout(&self) -> &'a Layout<'a> {
        match self {
            Queries::Alt0 { layout, .. } => layout,
            Queries::Amb(_) => panic!("Queries is ambiguous"),
        }
    }
    pub fn final_query(&self) -> &'a Opt0<'a> {
        match self {
            Queries::Alt0 { final_query, .. } => final_query,
            Queries::Amb(_) => panic!("Queries is ambiguous"),
        }
    }
}
impl<'a> Query<'a> {
    pub fn as_parse_tree(&'a self) -> ParseTree<'a> {
        ParseTree::Query(self)
    }
    pub fn child(&self, index: usize) -> Option<ParseTree<'a>> {
        match self {
            Query::Alt0 {
                alt_0,
                layout,
                semicolon,
                ..
            } => match index {
                0 => Some(ParseTree::Alt0(alt_0)),
                1 => Some(ParseTree::Layout(layout)),
                2 => Some(ParseTree::Token(*semicolon)),
                _ => None,
            },
            Query::Amb(alts) => alts.get(index).copied().map(ParseTree::Query),
        }
    }
    pub fn child_count(&self) -> usize {
        match self {
            Query::Alt0 { .. } => 3usize,
            Query::Amb(alts) => alts.len(),
        }
    }
    pub fn span(&self) -> Span {
        match self {
            Query::Alt0 { span, .. } => *span,
            Query::Amb(alts) => alts[0].span(),
        }
    }
    pub fn display_name(&self) -> &'static str {
        match self {
            Query::Amb(_) => "Amb",
            _ => "Query",
        }
    }
    pub fn origin(&self) -> Option<Origin> {
        None
    }
    pub fn alt_0(&self) -> &'a Alt0<'a> {
        match self {
            Query::Alt0 { alt_0, .. } => alt_0,
            Query::Amb(_) => panic!("Query is ambiguous"),
        }
    }
    pub fn layout(&self) -> &'a Layout<'a> {
        match self {
            Query::Alt0 { layout, .. } => layout,
            Query::Amb(_) => panic!("Query is ambiguous"),
        }
    }
    pub fn semicolon(&self) -> Token {
        match self {
            Query::Alt0 { semicolon, .. } => *semicolon,
            Query::Amb(_) => panic!("Query is ambiguous"),
        }
    }
}
